import unittest

from sms_lab import decode_submit, encode_submit, load_vectors


class SmsLabTests(unittest.TestCase):
    def test_fixed_vectors_decode_and_rebuild(self):
        # Expected wire bytes are committed fixtures, not generated by this test.
        for sample in load_vectors():
            with self.subTest(sample=sample["name"]):
                result = decode_submit(sample["pdu_hex"])
                for key in ("text", "recipient", "alphabet", "udl", "ud_octets"):
                    self.assertEqual(result[key], sample[key])
                self.assertEqual(result["serialized_hex"], sample["pdu_hex"])
                self.assertEqual(result["rebuilt_hex"], sample["pdu_hex"])

    def test_known_seven_septet_padding(self):
        pdu = "0001000B912120550521F300000731D98C56B3DD1A"
        self.assertEqual(encode_submit("1234567"), pdu)
        self.assertEqual(decode_submit(pdu)["text"], "1234567")
        self.assertEqual(decode_submit(pdu)["udl"], 7)

    def test_literal_at_sign_and_carriage_return(self):
        # A real final @/CR must not be discarded as septet padding.
        for text in ("@", "\r", "1234567@", "1234567\r", "^@", ""):
            with self.subTest(text=text):
                self.assertEqual(decode_submit(encode_submit(text))["text"], text)

    def test_single_part_boundaries(self):
        for text, alphabet, udl in (("A" * 160, "gsm7", 160), ("^" * 80, "gsm7", 160), ("你" * 70, "ucs2", 140)):
            with self.subTest(alphabet=alphabet, text_length=len(text)):
                result = decode_submit(encode_submit(text, alphabet=alphabet))
                self.assertEqual(result["text"], text)
                self.assertEqual(result["udl"], udl)
                self.assertEqual(result["ud_octets"], 140)
        for text, alphabet in (("A" * 161, "gsm7"), ("^" * 81, "gsm7"), ("你" * 71, "ucs2")):
            with self.subTest(alphabet=alphabet, text_length=len(text)):
                with self.assertRaises(ValueError):
                    encode_submit(text, alphabet=alphabet)

    def test_reject_truncated_or_extra_payload(self):
        pdu = load_vectors()[0]["pdu_hex"]
        for broken in (pdu[:-2], pdu + "00", "ZZ", "0", ""):
            with self.subTest(broken=broken):
                with self.assertRaises(ValueError):
                    decode_submit(broken)

    def test_reject_wrong_udl(self):
        raw = bytearray.fromhex(load_vectors()[0]["pdu_hex"])
        raw[13] = 12
        with self.assertRaises(ValueError):
            decode_submit(raw.hex())

    def test_reject_unsupported_flags_and_dcs(self):
        original = bytes.fromhex(load_vectors()[0]["pdu_hex"])
        for index, value in ((0, 7), (1, 0x41), (1, 0x11), (1, 0), (12, 4), (11, 1)):
            raw = bytearray(original)
            raw[index] = value
            with self.subTest(index=index, value=value):
                with self.assertRaises(ValueError):
                    decode_submit(raw.hex())

    def test_reject_invalid_address_padding(self):
        raw = bytearray.fromhex(load_vectors()[0]["pdu_hex"])
        raw[10] = 0x03
        with self.assertRaises(ValueError):
            decode_submit(raw.hex())

    def test_reject_non_bmp_ucs2(self):
        with self.assertRaises(ValueError):
            encode_submit("😀", alphabet="ucs2")
        with self.assertRaises(ValueError):
            decode_submit("0001000B912120550521F3000804D83DDE00")

    def test_reject_dangling_gsm_escape(self):
        with self.assertRaises(ValueError):
            decode_submit("0001000B912120550521F30000011B")

    def test_reference_and_even_length_address(self):
        result = decode_submit(encode_submit("OK", "+1202555012", reference=255))
        self.assertEqual(result["recipient"], "+1202555012")
        self.assertEqual(result["reference"], 255)
        self.assertTrue(result["semantic_rebuild"])


if __name__ == "__main__":
    unittest.main()
